"""Export a video-first homepage and chapter/source records, without WebGL."""
import argparse,hashlib,html,json,shutil,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];WORK=ROOT.parent/'real-footage-180';OUT=ROOT/'site/media/real-footage'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def manifest():
 titles=['前往目标点','低石：轮行受阻，逐轮跨越','R1：第一眼看见什么','已有任务返回的原模型','十二个实体预演世界','三策略：同一条仿真时钟','成功的边界与另场失败','连续到达尾段']
 sources=[['r1-opening-fixed','r1-opening-follow'],['low-stone-wheel','low-stone-full-lift','low-stone-depart'],['r1-first-person','r1-observation-input','r1-observation-external'],['r1-candidate-records'],['rehearsal-full-00'],['r1-synchronised-optimistic','r1-synchronised-conservative','r1-synchronised-imagination'],['r1-overlay','f3-004-contact'],['r1-tail']]
 durations=[15,20,18,22,30,42,16,17];start=0;chapters=[]
 for i,(title,ids,duration) in enumerate(zip(titles,sources,durations),1):
  clean=OUT/f'chapter-{i:02d}-clean.mp4';shutil.copy2(WORK/f'parts/{i:02d}.mp4',clean)
  poster=OUT/f'chapter-{i:02d}.jpg';subprocess.run(['ffmpeg','-v','error','-y','-ss','2','-i',str(clean),'-frames:v','1','-q:v','2',str(poster)],check=True)
  records=[]
  for name in ids:
   path=ROOT/'site/data/real-footage-sources'/f'{name}.json';assert path.exists(),path;d=json.loads(path.read_text());records.append({'id':name,'record':str(path.relative_to(ROOT/'site')),'record_sha256':sha(path),'original_path':d.get('source',d.get('source_index',', '.join(x['input_source'] for x in d.get('pairs',[])))),'source_time_s':d.get('source_time_range_s',d.get('original_sim_time_s')),'camera':d.get('camera','原网页录屏' if d.get('actual_browser_screen_recording') else '原相机或原帧机位')})
  if i==5:
   for w in range(1,12):
    p=ROOT/f'site/data/recordings/world-{w:02d}.json';d=json.loads(p.read_text())['recording'];t=d['source_time_range_s'];records.append({'id':f'world-{w:02d}','record':str(p.relative_to(ROOT/'site')),'record_sha256':sha(p),'used_file_time_s':[3,7],'original_path':d['source'],'source_time_s':[t[0]+(t[1]-t[0])*36/143,t[0]+(t[1]-t[0])*83/143],'camera':'原预演侧后跟拍（原录像3–7秒）'})
  c={'id':f'chapter-{i:02d}','title':title,'start_s':start,'duration_s':duration,'scene':'stress_v8_gate / 独立预检查' if i==2 else 'R1 + 另场 F3_004' if i==7 else 'R1 / stress_v8','kind':'原任务资产录屏' if i==4 else '原状态回放','poster':str(poster.relative_to(ROOT/'site')),'poster_sha256':sha(poster),'clean_video':str(clean.relative_to(ROOT/'site')),'clean_sha256':sha(clean),'sources':records}
  p=ROOT/'site/data/real-footage-chapters'/f'{i:02d}.json';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(c,ensure_ascii=False,indent=2));c['source_record']=str(p.relative_to(ROOT/'site'));chapters.append(c);start+=duration
 assert start==180;delivery=json.loads((WORK/'delivery.json').read_text());data={'schema':'beforestep-real-footage-180/v1','film':delivery,'preview':json.loads((WORK/'preview.json').read_text()),'chapters':chapters,'video_first':True,'webgl_required':False,'new_physics_runs':0,'new_generation_tasks':0}
 data['captions']=json.loads((WORK/'captions.json').read_text())['captions'];p=ROOT/'site/data/real-footage-180.json';p.write_text(json.dumps(data,ensure_ascii=False,indent=2));return data
def page(data,preview=False):
 film='media/real-footage/low-stone-preview.mp4' if preview else 'media/demo-v4.mp4';poster='media/real-footage/low-stone-preview.jpg' if preview else data['chapters'][0]['poster']
 cards=''
 for c in data.get('chapters',[]):
  start=c['start_s'];label=f'{start//60:02d}:{start%60:02d}';cards+=f'''<a class="chapter" href="{film}#t={start}" data-start="{start}" data-chapter="{c['id']}"><img src="{c['poster']}" width="1920" height="1080" alt="{html.escape(c['title'])}的实际片段" loading="lazy"><span class="chapter-time">{label}</span><strong>{html.escape(c['title'])}</strong><span>{c['duration_s']} 秒 · {c['scene']}</span></a>'''
 identity='stress_v8_gate / 同石独立预检查 / 原速片段剪辑' if preview else 'R1 / stress_v8 / 原运行状态回放'
 live_caption='轮行：接触门槛，停在这里。' if preview else '前往目标点。先看清这条路。'
 return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>先见一步 · 看机器人怎样行动</title><meta name="description" content="180秒原仿真实录：轮行受阻、逐轮跨越、候选世界预演、同步三策略和真实失败。"><link rel="icon" href="favicon.svg"><link rel="stylesheet" href="real-footage.css"></head><body data-preview="{'true' if preview else 'false'}"><header><a class="brand" href="index.html">先见一步 <span>BeforeStep</span></a><nav><a href="#chapters">分段回看</a><a href="levels.html">换条路看</a><a href="crossing.html">看轮腿动作</a><a href="#evidence">资料与来源</a></nav></header><main><section class="watch" id="watch"><p class="eyebrow">机器人原仿真记录 / 实录展示</p><h1>先在假设里走一步。</h1><p class="lead">看它在哪里受阻，怎样抬腿，如何先试走，再绕过去。</p><div class="watch-controls"><button id="play-recording" type="button">▶ 播放实录</button><button id="play-preview" type="button">看 25 秒低石样片</button><a id="direct-download" href="{film}" download>下载视频 ↗</a></div><div class="player-frame"><video id="main-player" controls playsinline preload="metadata" tabindex="0" poster="{poster}" src="{film}" aria-label="机器人实际仿真动作实录">浏览器无法播放视频，请使用下方下载链接。{'<track kind="subtitles" src="media/demo-v4.zh.vtt" srclang="zh" label="中文字幕">' if not preview else ''}</video><p id="video-error" role="alert" hidden>视频暂时未能加载。封面仍保留，可以通过“下载视频”打开原文件。</p></div><p id="current-caption" class="live-caption">{live_caption}</p><div id="strategy-legend" hidden><span>直冲</span><span>保守</span><span>先想象</span></div><p id="current-identity" class="identity">{identity}</p><details id="source-details"><summary>查看这一段的来源</summary><div id="current-sources"><p>画面来自原运行的实际状态与相机记录。</p><a href="{'data/real-footage-sources/low-stone-full-lift.json' if preview else 'data/real-footage-chapters/01.json'}">原时间、机位与文件记录 ↗</a></div></details></section><section id="chapters"><div class="heading"><p class="eyebrow">影片章节</p><h2>从动作，看到判断。</h2><p>点一个真实片段，直接回到影片中的这一段。</p></div><div class="chapter-grid">{cards}</div></section><section class="resources" id="evidence"><p class="eyebrow">继续观看与核对</p><h2>先看过程，再看依据。</h2><div class="resource-links"><a href="levels.html">十二条原场景与策略录像 ↗</a><a href="crossing.html">同路四车与轮腿动作 ↗</a><a href="gallery.html">辅助查看：原生成资产与任务 ↗</a><a href="report.html">完整报告、表格与失败记录 ↗</a><a href="data/real-footage-180.json">影片与每段来源清单 ↗</a><a href="docs/reviews/REAL_FOOTAGE_180.md">制作验收与补拍记录 ↗</a><a href="media/demo-v4-clean.mp4">无字幕母版 ↗</a></div><p class="note">这些画面是 MuJoCo 原运行记录的回放拍摄。没有新增实验，也没有实机或采样动作。低石预检查、R1 与 F3_004 在片中各自标明。</p></section></main><footer>BeforeStep · 先见一步 <a href="https://github.com/codezzzsleep/next-zenith-beforestep">源码、核心版本与原始证据 ↗</a></footer><script src="real-footage.js" defer></script></body></html>'''
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--preview',action='store_true');a=p.parse_args()
 data={'chapters':[]} if a.preview else manifest();target=ROOT/'site'/('real-footage-preview.html' if a.preview else 'index.html');target.write_text(page(data,a.preview));print('VIDEO-FIRST PAGE WRITTEN',target)
